"""Regenerates src/engine/metronome/ClickSamples.cpp from resources/sounds/*.wav (16-bit PCM, mono).

Run from the repository root after changing the sounds: python3 tools/embed_sounds.py
"""
import pathlib
import struct
import wave

ROOT = pathlib.Path(__file__).resolve().parent.parent
SOUNDS = [  # (file, C++ name)
    ("high.wav", "kClassicHigh"),
    ("low.wav", "kClassicLow"),
]

out = [
    "// SPDX-License-Identifier: MIT",
    "// Copyright (c) 2026 singularity098",
    "",
    "// Generated by tools/embed_sounds.py from resources/sounds/ - do not edit by hand.",
    "",
    '#include "engine/metronome/ClickSamples.hpp"',
    "",
    "namespace namsayin {",
    "",
    "namespace {",
    "",
]
defs = []
for filename, name in SOUNDS:
    with wave.open(str(ROOT / "resources" / "sounds" / filename)) as w:
        assert w.getsampwidth() == 2 and w.getnchannels() == 1, filename
        frames = w.readframes(w.getnframes())
        rate = w.getframerate()
    samples = struct.unpack("<%dh" % (len(frames) // 2), frames)
    out.append("const int16_t %sData[%d] = {" % (name, len(samples)))
    for i in range(0, len(samples), 16):
        out.append("    " + ", ".join(str(s) for s in samples[i:i + 16]) + ",")
    out.append("};")
    out.append("")
    defs.append("const ClickSample %s = { %sData, %d, %d };" % (name, name, len(samples), rate))

out += ["} // namespace", ""] + defs + ["", "} // namespace namsayin", ""]
(ROOT / "src" / "engine" / "metronome" / "ClickSamples.cpp").write_text("\n".join(out))
